     1→// api/saveProject/index.js
     2→// POST /api/saveProject
     3→// Body: { project: { id, name, sections, items, schedule, ... } }
     4→//
     5→// Saves one project as its own independent Cosmos document.
     6→// Document ID: "adh-proj-{project.id}"
     7→//
     8→// Concurrent edits to DIFFERENT projects never conflict — they hit
     9→// completely separate documents with separate ETags.
    10→//
    11→// Concurrent edits to the SAME project are handled with:
    12→//   - ETag optimistic concurrency (up to 5 retries on 412)
    13→//   - Item-level merge: two supers editing different SI items both survive
    14→//   - Dirty-flag guard: items flagged _dirty on the server are not overwritten
    15→//     by stale incoming data (last-modified-wins per item)
    16→
    17→const { CosmosClient } = require("@azure/cosmos");
    18→const https = require("https");
    19→
    20→// Enforce TCP connection reuse to prevent socket exhaustion
    21→const keepAliveAgent = new https.Agent({ keepAlive: true });
    22→
    23→const client    = new CosmosClient({
    24→  connectionString: process.env.COSMOS_DB_CONNECTION_STRING,
    25→  agent: keepAliveAgent
    26→});
    27→const database  = client.database("Auditdata");
    28→const container = database.container("Audits");
    29→const MAX_RETRIES = 5;
    30→
    31→// ── Per-field timestamp merge ─────────────────────────────────────────────────
    32→// If both sides have a _fieldTs for a key, the newer timestamp wins.
    33→// Falls back to "incoming wins" when timestamps are absent.
    34→function mergeFields(current, incoming) {
    35→  const cTs = current._fieldTs  || {};
    36→  const iTs = incoming._fieldTs || {};
    37→  const result = Object.assign({}, current);
    38→
    39→  Object.keys(incoming).forEach(k => {
    40→    if (k === "_fieldTs") return;
    41→    const cTime = cTs[k];
    42→    const iTime = iTs[k];
    43→    if (cTime !== undefined && iTime !== undefined && cTime > iTime) {
    44→      // Current is newer on this field — keep it
    45→      return;
    46→    }
    47→    result[k] = incoming[k];
    48→  });
    49→
    50→  // Merge fieldTs maps — keep the max per field
    51→  if (iTs && Object.keys(iTs).length) {
    52→    const merged = Object.assign({}, cTs);
    53→    Object.keys(iTs).forEach(k => {
    54→      if (merged[k] === undefined || iTs[k] > merged[k]) merged[k] = iTs[k];
    55→    });
    56→    result._fieldTs = merged;
    57→  }
    58→
    59→  return result;
    60→}
    61→
    62→// ── Item-level merge ──────────────────────────────────────────────────────────
    63→// Merges incoming items into the current item list.
    64→// For items that exist on both sides, field-level timestamps resolve conflicts.
    65→// Items only on the current side are kept (created by another device offline).
    66→// Items only on the incoming side are added.
    67→// Photos are NEVER stored in Cosmos — always strip them from incoming.
    68→function mergeItems(currentItems, incomingItems) {
    69→  const currentMap  = new Map((currentItems  || []).map(i => [i.id, i]));
    70→  const incomingMap = new Map((incomingItems || []).map(i => [i.id, i]));
    71→
    72→  // Process incoming items
    73→  incomingMap.forEach((incoming, id) => {
    74→    // Always strip photos from what gets written to Cosmos —
    75→    // photos live in IndexedDB on the client, Azure Blob for URLs.
    76→    const incomingClean = Object.assign({}, incoming, {
    77→      photos: (incoming.photos || [])
    78→        .filter(p => p.url)
    79→        .map(p => ({ url: p.url, caption: p.caption || "", takenAt: p.takenAt || "" })),
    80→      attachments: (incoming.attachments || [])
    81→        .map(a => ({
    82→          id: a.id, name: a.name, type: a.type, ext: a.ext,
    83→          icon: a.icon, size: a.size, addedAt: a.addedAt, addedBy: a.addedBy
    84→        }))
    85→    });
    86→
    87→    if (currentMap.has(id)) {
    88→      // Merge field by field — field timestamps resolve conflicts
    89→      const merged = mergeFields(currentMap.get(id), incomingClean);
    90→      // Preserve any cloud-URL photos already on the current side
    91→      // that the client didn't send back (it strips base64, keeps URLs)
    92→      const currentUrlPhotos = (currentMap.get(id).photos || []).filter(p => p.url);
    93→      const incomingUrls = new Set((incomingClean.photos || []).map(p => p.url));
    94→      const extraPhotos = currentUrlPhotos.filter(p => !incomingUrls.has(p.url));
    95→      merged.photos = [...(incomingClean.photos || []), ...extraPhotos];
    96→      currentMap.set(id, merged);
    97→    } else {
    98→      // New item — just add it
    99→      currentMap.set(id, incomingClean);
   100→    }
   101→  });
   102→
   103→  // Items only on current side are kept as-is (created by another device)
   104→  return [...currentMap.values()];
   105→}
   106→
   107→module.exports = async function (context, req) {
   108→  context.res = { headers: { "Content-Type": "application/json" } };
   109→
   110→  if (req.method === "OPTIONS") {
   111→    context.res = { status: 204, body: "" };
   112→    return;
   113→  }
   114→
   115→  if (!req.body || !req.body.project) {
   116→    context.res.status = 400;
   117→    context.res.body   = { ok: false, error: "Body must contain { project: { id, ... } }" };
   118→    return;
   119→  }
   120→
   121→  const incoming = req.body.project;
   122→
   123→  if (!incoming.id || typeof incoming.id !== "string") {
   124→    context.res.status = 400;
   125→    context.res.body   = { ok: false, error: "project.id is required" };
   126→    return;
   127→  }
   128→
   129→  // Sanitize project ID
   130→  if (!/^[a-zA-Z0-9_-]+$/.test(incoming.id)) {
   131→    context.res.status = 400;
   132→    context.res.body   = { ok: false, error: "Invalid project ID format" };
   133→    return;
   134→  }
   135→
   136→  const docId = "adh-proj-" + incoming.id;
   137→
   138→  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
   139→    try {
   140→      // ── 1. Read current document + ETag ────────────────────────────────────
   141→      let current, etag;
   142→      try {
   143→        const { resource } = await container.item(docId, docId).read();
   144→        if (!resource) { current = null; etag = null; }
   145→        else           { current = resource; etag = resource._etag; }
   146→      } catch (e) {
   147→        if (e.code === 404) { current = null; etag = null; }
   148→        else throw e;
   149→      }
   150→
   151→      // ── 2. Build the document to write ─────────────────────────────────────
   152→      let docToWrite;
   153→
   154→      if (!current) {
   155→        // Brand new project — write it directly (strip photos from items)
   156→        docToWrite = Object.assign({}, incoming, {
   157→          id:        docId,        // Cosmos document ID
   158→          projectId: incoming.id,  // Original app-level ID preserved here
   159→          ownedBy:   incoming.ownedBy || '',  // User identity — never overwritten
   160→          items: mergeItems([], incoming.items || []),
   161→          coverPhoto: null,        // Never in Cosmos — too large
   162→          floorPlan: incoming.floorPlan
   163→            ? Object.assign({}, incoming.floorPlan, { imageData: null })
   164→            : undefined,
   165→          _savedAt: incoming._savedAt || Date.now()
   166→        });
   167→      } else {
   168→        // Existing project — merge carefully.
   169→        // ownedBy is immutable once set — never let incoming overwrite it
   170→        // unless the current doc has no owner yet (legacy migration).
   171→        const ownedBy = current.ownedBy || incoming.ownedBy || '';
   172→
   173→        // Safety guard: if the project already has an owner and the incoming
   174→        // request is from a different user, reject the write.
   175→        if (current.ownedBy && incoming.ownedBy && current.ownedBy !== incoming.ownedBy) {
   176→          context.log.warn(`[saveProject] Ownership mismatch on ${incoming.id}: owner=${current.ownedBy} requester=${incoming.ownedBy}`);
   177→          context.res.status = 403;
   178→          context.res.body   = { ok: false, error: "Forbidden — you do not own this project." };
   179→          return;
   180→        }
   181→
   182→        docToWrite = Object.assign({}, current, incoming, {
   183→          id:        docId,
   184→          projectId: incoming.id,
   185→          ownedBy:   ownedBy,  // Preserve original owner
   186→          items:     mergeItems(current.items || [], incoming.items || []),
   187→          coverPhoto: null,
   188→          floorPlan: incoming.floorPlan
   189→            ? Object.assign({}, incoming.floorPlan, { imageData: null })
   190→            : (current.floorPlan || undefined),
   191→          _savedAt: incoming._savedAt || Date.now()
   192→        });
   193→      }
   194→
   195→      // ── 3. Write with ETag guard ────────────────────────────────────────────
   196→      const upsertOptions = etag
   197→        ? { accessCondition: { type: "IfMatch", condition: etag } }
   198→        : {};
   199→
   200→      const { resource: saved } = await container.items.upsert(docToWrite, upsertOptions);
   201→
   202→      context.log(`[saveProject] ✓ ${incoming.id} (${incoming.name || "?"}) attempt=${attempt}`);
   203→      context.res.status = 200;
   204→      context.res.body   = { ok: true, _ts: saved._ts, _savedAt: saved._savedAt };
   205→      return;
   206→
   207→    } catch (err) {
   208→      if (err.code === 412 && attempt < MAX_RETRIES) {
   209→        context.log.warn(`[saveProject] ETag conflict on ${incoming.id}, retry ${attempt}/${MAX_RETRIES}`);
   210→        await new Promise(r => setTimeout(r, 80 * attempt));
   211→        continue;
   212→      }
   213→      context.log.error(`[saveProject] Error on ${incoming.id}:`, err.message);
   214→      context.res.status = err.code === 412 ? 409 : 500;
   215→      context.res.body   = { ok: false, error: err.message };
   216→      return;
   217→    }
   218→  }
   219→};
